import type { Matrix } from './math/matrix.js';
export type Point = number[];
export interface PathData {
    c?: boolean;
    v: Point[];
    i: Point[];
    o: Point[];
}
export interface GradientStop {
    p: number;
    r: number;
    g: number;
    b: number;
    a: number;
}
export interface ColorPaint {
    kind: 'color';
    color: number[];
    alpha: number;
    rule?: number;
}
export interface GradientPaint {
    kind: 'linear' | 'radial';
    s: number[];
    e: number[];
    h?: number;
    a?: number;
    stops: GradientStop[];
    alpha: number;
    rule?: number;
}
export type FillPaint = ColorPaint | GradientPaint;
export interface StrokeProps {
    width: number;
    cap: number;
    join: number;
    miter?: number;
    dash?: number[];
    dashOffset?: number;
}
export type StrokePaint = FillPaint & StrokeProps;
export interface ClipShape {
    paths: PathData[];
    matrix: Matrix;
    rule?: number;
    coverage?: number;
}
export interface Clip {
    shapes: ClipShape[];
    mode: 1 | 2 | 3;
    alpha?: number;
}
export interface ColorMatrixFilter {
    kind: 'colorMatrix';
    values: number[];
}
export interface ColorTableFilter {
    kind: 'colorTable';
    r?: number[];
    g?: number[];
    b?: number[];
    a?: number[];
}
export interface BlurFilter {
    kind: 'blur';
    sigmaX: number;
    sigmaY: number;
    repeatEdge?: boolean;
}
export interface ShadowFilter {
    kind: 'shadow';
    color: number[];
    alpha: number;
    offsetX: number;
    offsetY: number;
    sigma: number;
}
export type Filter = ColorMatrixFilter | ColorTableFilter | BlurFilter | ShadowFilter;
interface BaseOp {
    matrix: Matrix;
    clips?: Clip[];
    filters?: Filter[];
    blend?: number;
    static?: boolean;
}
export interface ShapeOp extends BaseOp {
    kind: 'shape';
    paths: PathData[];
    fills: FillPaint[];
    strokes: StrokePaint[];
}
export interface ImageOp extends BaseOp {
    kind: 'image';
    src: string;
    assetId?: string;
    width: number;
    height: number;
    alpha: number;
    paths?: PathData[];
    fills?: FillPaint[];
    strokes?: StrokePaint[];
}
export type DrawOp = ShapeOp | ImageOp;
export interface Scene {
    width: number;
    height: number;
    ops: DrawOp[];
}
export {};
